#pragma once
#include "module/i2c_register_device.hpp"
namespace fw::module{struct Mpu6050Sample{std::int16_t accelX,accelY,accelZ,temp,gyroX,gyroY,gyroZ;float accelXG()const noexcept{return accelX/16384.0F;}float accelYG()const noexcept{return accelY/16384.0F;}float accelZG()const noexcept{return accelZ/16384.0F;}float gyroXDps()const noexcept{return gyroX/131.0F;}float gyroYDps()const noexcept{return gyroY/131.0F;}float gyroZDps()const noexcept{return gyroZ/131.0F;}float temperatureC()const noexcept{return temp/340.0F+36.53F;}};class Mpu6050{public:explicit Mpu6050(fw::bsp::II2cBus&bus,std::uint16_t address7bit=0x68):device_(bus,address7bit){}fw::Result<void>initialize();fw::Result<Mpu6050Sample>read();bool ready()const noexcept{return ready_;}private:fw::module::I2cRegisterDevice device_;bool ready_{false};};}
